function notify(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function current(){return workspace.projects.find(p=>p.id===workspace.activeProjectId)||null;}
function setCloudStatus(mode,label){const button=$('#account-button');button.classList.remove('connected','syncing','error');if(mode)button.classList.add(mode);$('#account-label').textContent=label;}
async function syncProject(project,{quiet=false}={}){
  if(!session||!project)return;
  setCloudStatus('syncing','Syncing…');
  try{await upsertCloudProject(project);setCloudStatus('connected',session.user.email);if(!quiet)$('#save-status').textContent='Saved to cloud';}
  catch(error){setCloudStatus('error','Sync paused');if(!quiet)notify(error.message);}
}
function queueCloudProject(project){if(!session)return;clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>syncProject(project),500);}
async function syncWorkspace(){
  if(!session)return;
  setCloudStatus('syncing','Connecting…');
  try{
    const recordedOwner=localStorage.getItem(CLOUD_OWNER_KEY),localProjects=!recordedOwner||recordedOwner===session.user.id?workspace.projects:[],[cloudProjects,cloudTemplates]=await Promise.all([fetchCloudProjects(),fetchCloudTemplates()]),cloudById=new Map(cloudProjects.map(p=>[p.id,p]));templates=cloudTemplates;
    workspace=validateWorkspace({...workspace,projects:mergeProjectSets(localProjects,cloudProjects)});saveWorkspace(workspace);
    const uploads=localProjects.filter(p=>p.accessRole!=='viewer'&&(!cloudById.has(p.id)||String(p.updatedAt||'')>String(cloudById.get(p.id).updatedAt||'')));
    await Promise.all(uploads.map(p=>upsertCloudProject(p)));
    localStorage.setItem(CLOUD_OWNER_KEY,session.user.id);active=current();setCloudStatus('connected',session.user.email);renderDashboard();
    notify(uploads.length?'Local projects were merged with your cloud workspace.':'Cloud workspace is up to date.');
  }catch(error){setCloudStatus('error','Sync paused');notify(`Cloud sync paused: ${error.message}`);renderDashboard();}
}
function persist(){if(!active||active.accessRole==='viewer')return;active.updatedAt=new Date().toISOString();try{saveWorkspace(workspace);$('#save-status').textContent='Saved locally';queueCloudProject(active);}catch{$('#save-status').textContent='Save failed';notify('Local storage is full. Download a backup before continuing.');}}
function changed(){if(!active||active.accessRole==='viewer')return;$('#save-status').textContent='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{persist();renderReadiness();},250);}
function statusText(p){const r=reviewProject(p);return r.ready?'Ready for issue review':`${r.critical} critical gap${r.critical===1?'':'s'}`;}

function renderDashboard(){
  active=null;workspace.activeProjectId=null;saveWorkspace(workspace);$('#editor').hidden=true;$('#dashboard').hidden=false;$('#current-project-name').textContent='Projects';$$('.editor-only').forEach(x=>x.hidden=true);
  const live=workspace.projects.filter(p=>!p.archived),archived=workspace.projects.filter(p=>p.archived),ready=live.filter(p=>reviewProject(p).ready).length;
  $('#portfolio-summary').innerHTML=`<article><span>Active projects</span><strong>${live.length}</strong></article><article><span>Ready for review</span><strong>${ready}</strong></article><article><span>Frozen issues</span><strong>${workspace.projects.reduce((n,p)=>n+p.releases.length,0)}</strong></article><article><span>Archived</span><strong>${archived.length}</strong></article>`;
  const q=$('#project-search').value.trim().toLowerCase(),matches=workspace.projects.filter(p=>`${p.fields.projectName} ${p.fields.projectCode}`.toLowerCase().includes(q));
  $('#project-list').innerHTML=matches.length?matches.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(p=>{const r=reviewProject(p),shared=p.accessRole&&p.accessRole!=='owner';return `<article class="project-card ${p.archived?'archived':''}" data-id="${p.id}"><div class="project-card-top"><span class="project-code">${esc(p.fields.projectCode||'NO CODE')}</span><span class="score ${r.ready?'ready':''}">${r.score}%</span></div><h3>${esc(p.fields.projectName||'Untitled project')}</h3><p>${esc(p.fields.client||'Client not assigned')}</p>${shared?`<span class="access-badge ${esc(p.accessRole)}">SHARED · ${esc(p.accessRole.toUpperCase())}</span>`:''}<div class="project-meta"><span>${statusText(p)}</span><span>${p.releases.length} issue${p.releases.length===1?'':'s'}</span></div><div class="card-actions"><button data-action="open" class="button primary">Open</button><button data-action="duplicate" class="icon-button" title="Duplicate project">⧉</button>${shared?'':`<button data-action="archive" class="icon-button" title="${p.archived?'Restore':'Archive'}">${p.archived?'↥':'⌄'}</button>`}<button data-action="delete" class="icon-button danger-text" title="${shared?'Leave shared project':'Delete'}">×</button></div></article>`}).join(''):`<div class="empty-state"><strong>No projects yet</strong><p>Create a BEP project. Your work is saved automatically on this device.</p></div>`;
}
function openProject(id){workspace.activeProjectId=id;active=current();if(!active)return;saveWorkspace(workspace);$('#dashboard').hidden=true;$('#editor').hidden=false;$$('.editor-only').forEach(x=>x.hidden=false);$('#current-project-name').textContent=active.fields.projectName||'Untitled project';$('#print').hidden=false;showView('project');}
function renderReadiness(){if(!active)return;const r=reviewProject(active);$('#readiness-value').textContent=`${r.score}%`;$('#readiness-bar').style.width=`${r.score}%`;$('#readiness-label').textContent=r.ready?'No critical gaps block issue':`${r.critical} critical · ${r.warnings} warning${r.warnings===1?'':'s'}`;$('#current-project-name').textContent=active.fields.projectName||'Untitled project';}
function fieldInput([key,label,type,required,options]){const value=active.fields[key]||'',req=required?'<span class="required">Required</span>':'';if(type==='textarea')return `<label class="field wide"><span>${label}${req}</span><textarea data-field="${key}" rows="4">${esc(value)}</textarea></label>`;if(type==='select')return `<label class="field"><span>${label}${req}</span><select data-field="${key}">${options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;return `<label class="field"><span>${label}${req}</span><input data-field="${key}" type="${type}" value="${esc(value)}"></label>`;}
function fieldsCard(title,group){return `<section class="form-card"><h2>${title}</h2><div class="field-grid">${fieldGroups[group].map(fieldInput).join('')}</div></section>`;}
function listCell(key,rowIndex,row,[column,,type='text',options=[]]){const value=row[column]||'';if(type==='select')return `<select data-list="${key}" data-row="${rowIndex}" data-col="${column}">${options.map(option=>`<option ${value===option?'selected':''}>${esc(option)}</option>`).join('')}</select>`;return `<input data-list="${key}" data-row="${rowIndex}" data-col="${column}" type="${type}" value="${esc(value)}">`;}
function listEditor(key){const schema=listSchemas[key],rows=active.lists[key];return `<section class="form-card table-card" data-list-card="${key}"><div class="card-heading"><div><h2>${schema.label}</h2><p>${rows.length} record${rows.length===1?'':'s'}</p></div><div class="table-tools"><button class="button ghost" data-export-csv="${key}">CSV ↓</button><button class="button ghost" data-import-csv="${key}">CSV ↑</button><button class="button secondary" data-add-row="${key}">+ Add row</button></div></div><div class="table-scroll"><table class="editor-table"><thead><tr>${schema.columns.map(c=>`<th>${c[1]}</th>`).join('')}<th></th></tr></thead><tbody>${rows.length?rows.map((row,i)=>`<tr>${schema.columns.map(column=>`<td>${listCell(key,i,row,column)}</td>`).join('')}<td><button class="row-delete" data-delete-row="${key}" data-row="${i}" aria-label="Delete row">×</button></td></tr>`).join(''):`<tr><td colspan="${schema.columns.length+1}" class="empty-cell">No records yet — add the first row.</td></tr>`}</tbody></table></div></section>`;}
function formatBytes(bytes){if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1048576).toFixed(1)} MB`;}
function renderFiles(root){const files=active.attachments||[];root.innerHTML=`<section class="form-card upload-card"><div><h2>Private project attachments</h2><p>Upload approved references, diagrams and appendices. Files are stored privately and linked to this project.</p></div><label class="button primary" for="attachment-upload">Upload files<input id="attachment-upload" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.csv,.xlsx,.docx" hidden></label></section><section class="form-card"><div class="card-heading"><h2>Uploaded files</h2><span>${files.length} file${files.length===1?'':'s'}</span></div><div class="file-list">${files.length?files.map(file=>`<article><div class="file-icon">${esc((file.name.split('.').pop()||'FILE').slice(0,4).toUpperCase())}</div><div><strong>${esc(file.name)}</strong><span>${formatBytes(file.size)} · ${esc(new Date(file.uploadedAt).toLocaleDateString('en-GB'))}</span></div><div class="file-actions"><button class="button ghost" data-download-file="${esc(file.id)}">Download</button><button class="icon-button danger-text" data-delete-file="${esc(file.id)}" aria-label="Delete file">×</button></div></article>`).join(''):'<p class="empty-cell">No files uploaded yet.</p>'}</div></section>${listEditor('appendices')}${listEditor('decisions')}`;}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);}
function renderTemplates(root){
  const applied=active.appliedTemplates||[],conflicts=active.templateConflicts||[];
  root.innerHTML=`<section class="data-hero"><div><span class="eyebrow">SCHEDULE EXCHANGE</span><h2>Excel & CSV workspace</h2><p>Export every advanced BEP schedule in one structured workbook, or import reviewed data with a controlled merge or replacement.</p></div><div class="data-actions"><button class="button primary" id="export-workbook">Export Excel workbook</button><button class="button secondary" id="import-workbook">Import Excel workbook</button></div></section><section class="form-card"><div class="card-heading"><div><h2>Reusable template library</h2><p>Company baselines and client requirement packs are private to your account.</p></div><button class="button primary" id="new-template">+ Create from this project</button></div><div class="template-grid">${templates.length?templates.map(t=>`<article class="template-card ${t.type}"><div class="template-badge">${t.type==='company'?'COMPANY BASELINE':'CLIENT REQUIREMENTS'}</div><h3>${esc(t.name)}</h3><p>${esc(t.description||'No description')}</p><dl><div><dt>Version</dt><dd>${esc(t.version)}</dd></div><div><dt>Source</dt><dd>${esc(t.sourceReference||'Internal baseline')}</dd></div></dl><div class="template-actions"><button class="button secondary" data-apply-template="${t.id}">Preview & apply</button><button class="icon-button danger-text" data-delete-template="${t.id}" aria-label="Delete template">×</button></div></article>`).join(''):'<div class="empty-state compact"><strong>No templates yet</strong><p>Create a controlled baseline from the current project.</p></div>'}</div></section><section class="form-card"><div class="card-heading"><h2>Applied template register</h2><span>${applied.length} application${applied.length===1?'':'s'}</span></div>${applied.length?`<div class="audit-list">${applied.slice().reverse().map(x=>`<article><strong>${esc(x.name)}</strong><span>${esc(x.type)} · v${esc(x.version)} · ${esc(x.mode)} · ${esc(new Date(x.appliedAt).toLocaleString('en-GB'))}</span><small>${esc(x.sourceReference||'Internal baseline')}</small></article>`).join('')}</div>`:'<p class="empty-cell">No template has been applied to this project.</p>'}${conflicts.length?`<div class="conflict-box"><strong>${conflicts.length} retained conflict${conflicts.length===1?'':'s'}</strong><p>Existing project values were preserved during a merge. Review them before issue.</p><button class="button ghost" id="clear-conflicts">Mark reviewed</button></div>`:''}</section>`;
}
function startImport(tables,warnings=[]){pendingImport={tables,warnings};const total=Object.values(tables).reduce((n,r)=>n+r.length,0);$('#import-summary').innerHTML=`<div class="import-stats"><strong>${Object.keys(tables).length}</strong><span>schedules</span><strong>${total}</strong><span>rows</span></div>${Object.entries(tables).map(([key,rows])=>`<p><b>${esc(listSchemas[key].label)}</b><span>${rows.length} incoming row${rows.length===1?'':'s'}</span></p>`).join('')}${warnings.map(x=>`<p class="import-warning">${esc(x)}</p>`).join('')}`;$('#import-dialog').showModal();}
async function applySelectedTemplate(id){const template=templates.find(t=>t.id===id);if(!template)return;const impact=previewTemplate(active,template);pendingTemplate=template;$('#template-impact').innerHTML=`<div class="template-source"><b>${esc(template.name)}</b><span>${esc(template.type==='client'?'Client requirement pack':'Company baseline')} · v${esc(template.version)}</span><small>Source: ${esc(template.sourceReference||'Internal baseline')}</small></div><div class="import-stats"><strong>${impact.rows}</strong><span>rows</span><strong>${impact.conflicts.length}</strong><span>potential conflicts</span></div><p>${impact.fields} fields, ${impact.schedules} schedules and ${impact.modules} module settings are included. Merge mode preserves established project values and records conflicts for review.</p>`;$('#template-apply-dialog').showModal();}
function renderAppearance(root){
  const count=Number(active.style.logoCount||0),logos=active.style.logos||[];
  const slots=Array.from({length:count},(_,index)=>{const logo=logos[index]||{path:'',name:'',placement:'both'};return `<article class="logo-slot"><div><span class="logo-order">LOGO ${index+1}</span><strong>${esc(logo.name||'No file uploaded')}</strong><small>${logo.path?'Stored privately for this project.':'Upload a transparent PNG or JPEG up to 5 MB.'}</small></div><label class="field"><span>Placement</span><select data-logo-placement="${index}"><option value="cover" ${logo.placement==='cover'?'selected':''}>Cover only</option><option value="both" ${logo.placement!=='cover'?'selected':''}>Cover + page header</option></select></label><div class="logo-slot-actions"><label class="button secondary" for="logo-upload-${index}">${logo.path?'Replace':'Upload'}<input id="logo-upload-${index}" data-logo-upload="${index}" type="file" accept="image/png,image/jpeg" hidden></label>${logo.path?`<button class="button ghost danger-text" data-remove-logo="${index}">Remove</button>`:''}</div></article>`;}).join('');
  root.innerHTML=`<section class="form-card"><div class="card-heading"><div><h2>Project logos</h2><p>Choose up to four logos, their order, and whether each appears on the cover only or on every page header.</p></div><label class="field logo-count"><span>Number of logos</span><select id="logo-count">${[0,1,2,3,4].map(n=>`<option value="${n}" ${count===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="logo-slots">${slots||'<p class="empty-cell">No logos will be included in this document.</p>'}</div></section><section class="form-card"><h2>Document identity</h2><div class="field-grid"><label class="field"><span>Primary colour</span><input type="color" data-style="accent" value="${active.style.accent}"></label><label class="field"><span>Document typeface</span><select data-style="font"><option value="sans" ${active.style.font==='sans'?'selected':''}>Arial / Sans serif</option><option value="serif" ${active.style.font==='serif'?'selected':''}>Georgia / Serif</option></select></label><label class="check"><input type="checkbox" data-style="cover" ${active.style.cover?'checked':''}>Show cover</label><label class="check"><input type="checkbox" data-style="toc" ${active.style.toc?'checked':''}>Show table of contents</label><label class="check"><input type="checkbox" data-style="showNotApplicable" ${active.style.showNotApplicable?'checked':''}>Show excluded-module register</label></div></section><section class="form-card"><h2>Printing</h2><p>The preview is paginated to A4 with repeated headers, footers, page numbers and controlled table breaks. In the browser print dialog, use A4, enable Background graphics, and disable the browser's own Headers and footers.</p><button class="button primary" data-open-preview>Open paginated preview</button></section>`;
}
const dateLabel=value=>value?new Date(value).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'—';
const accessOwner=()=>!active.accessRole||active.accessRole==='owner';
const shareState=item=>item.revoked_at?'Revoked':new Date(item.expires_at)<=new Date()?'Expired':'Active';
function renderSharing(root){
  if(!accessOwner()){
    root.innerHTML=`<section class="access-hero"><span class="access-badge ${esc(active.accessRole)}">${esc((active.accessRole||'viewer').toUpperCase())} ACCESS</span><h2>This BEP is shared with you</h2><p>${active.accessRole==='editor'?'You can update the BEP and your changes sync to the same project. This release is not live co-authoring, so coordinate before editing the same project at the same time.':'You can review, preview and print this BEP, but cannot change its content.'}</p><button class="button ghost danger-text" id="leave-project">Leave shared project</button></section>`;
    return;
  }
  const activeShares=publicShares.filter(item=>shareState(item)==='Active').length;
  root.innerHTML=`<section class="sharing-grid"><article class="form-card share-builder"><span class="eyebrow">PUBLIC / READ ONLY</span><h2>Share a preview</h2><p>Publish a frozen snapshot of the current BEP. Anyone with the private link can view and print it without signing in.</p><form id="public-share-form"><label class="field"><span>Link title</span><input name="title" maxlength="180" value="${esc(`${active.fields.projectName||'BEP'} preview`)}" required></label><label class="field"><span>Expires after</span><select name="days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option></select></label><button class="button primary" type="submit">Create public preview</button></form>${lastShareLink?`<div class="created-link"><strong>Preview link created</strong><input value="${esc(lastShareLink)}" readonly><button class="button secondary" data-copy-link="${esc(lastShareLink)}">Copy link</button><small>This full link is shown once. Store it before leaving this page.</small></div>`:''}</article><article class="form-card share-builder"><span class="eyebrow">COLLABORATION</span><h2>Invite a user</h2><p>Create a one-use invitation link for this BEP. Editor changes sync to the same project, but simultaneous live co-authoring is not enabled in this release.</p><form id="project-invite-form"><label class="field"><span>Permission</span><select name="role"><option value="editor">Editor — can change the BEP</option><option value="viewer">Viewer — read and print only</option></select></label><label class="field"><span>Invitation expires after</span><select name="days"><option value="1">1 day</option><option value="7" selected>7 days</option><option value="30">30 days</option></select></label><button class="button primary" type="submit">Create invitation link</button></form>${lastInviteLink?`<div class="created-link"><strong>Invitation link created</strong><input value="${esc(lastInviteLink)}" readonly><button class="button secondary" data-copy-link="${esc(lastInviteLink)}">Copy link</button><small>The link can be accepted once and should be sent only to the intended person.</small></div>`:''}</article></section><section class="form-card"><div class="card-heading"><div><h2>Public previews</h2><p>Each link is a snapshot. Later BEP edits do not silently change an already shared preview.</p></div><span>${activeShares} active</span></div><div class="access-list">${publicShares.length?publicShares.map(item=>`<article><div><strong>${esc(item.title)}</strong><span>${shareState(item)} · expires ${esc(dateLabel(item.expires_at))}</span></div>${shareState(item)==='Active'?`<button class="button ghost danger-text" data-revoke-share="${item.id}">Revoke</button>`:''}</article>`).join(''):'<p class="empty-cell">No public previews created.</p>'}</div></section><section class="sharing-grid"><article class="form-card"><div class="card-heading"><h2>Project members</h2><span>${collaborators.length} collaborator${collaborators.length===1?'':'s'}</span></div><div class="access-list">${collaborators.length?collaborators.map(item=>`<article><div><strong>${esc(item.collaborator_email||'Signed-in collaborator')}</strong><span>${esc(item.role)} · joined ${esc(dateLabel(item.accepted_at))}</span></div><button class="button ghost danger-text" data-remove-collaborator="${esc(item.user_id)}">Remove</button></article>`).join(''):'<p class="empty-cell">Only you can access this project.</p>'}</div></article><article class="form-card"><div class="card-heading"><h2>Invitation history</h2><span>${projectInvites.length}</span></div><div class="access-list">${projectInvites.length?projectInvites.map(item=>{const state=item.revoked_at?'Revoked':item.accepted_at?'Accepted':new Date(item.expires_at)<=new Date()?'Expired':'Pending';return `<article><div><strong>${esc(item.role.toUpperCase())}</strong><span>${state} · expires ${esc(dateLabel(item.expires_at))}</span></div>${state==='Pending'?`<button class="button ghost danger-text" data-revoke-invite="${item.id}">Revoke</button>`:''}</article>`;}).join(''):'<p class="empty-cell">No invitations created.</p>'}</div></article></section>`;
}
function enforceAccess(root){if(active.accessRole!=='viewer'||activeView==='sharing')return;root.insertAdjacentHTML('afterbegin','<div class="readonly-banner"><strong>View-only access</strong><span>Editing controls are disabled for this shared BEP.</span></div>');root.querySelectorAll('input,select,textarea,button').forEach(element=>{if(!element.matches('[data-open-preview],[data-issue-code]'))element.disabled=true;});}
function renderFormView(){
  if(!active)return;const root=$('#form-view');
  if(activeView==='project')root.innerHTML=fieldsCard('Project information','project')+fieldsCard('Appointment & scope','appointment');
  else if(activeView==='templates')renderTemplates(root);
  else if(activeView==='organization')root.innerHTML=viewLists.organization.map(listEditor).join('');
  else if(activeView==='information')root.innerHTML=fieldsCard('Data environment & procedures','information')+viewLists.information.map(listEditor).join('');
  else if(activeView==='technical')root.innerHTML=fieldsCard('Technical standards','technical')+viewLists.technical.map(listEditor).join('');
  else if(activeView==='coordination')root.innerHTML=fieldsCard('Coordination & closeout settings','coordination')+viewLists.coordination.map(listEditor).join('');
  else if(activeView==='modules')root.innerHTML=moduleGroups.map(g=>`<section class="form-card"><h2>${g.label}</h2><div class="module-grid">${modules.filter(m=>m.group===g.id).map(m=>`<article class="module-card" data-module-card="${m.id}"><div><strong>${m.ar}</strong><span>${m.title}</span><p>${m.desc}</p></div><select data-module="${m.id}">${statuses.map(s=>`<option value="${s.value}" ${active.moduleStates[m.id]===s.value?'selected':''}>${s.label}</option>`).join('')}</select><label>Project-specific text<textarea data-note="${m.id}" rows="2" placeholder="Added to the end of this section">${esc(active.notes[m.id]||'')}</textarea></label></article>`).join('')}</div></section>`).join('');
  else if(activeView==='files')renderFiles(root);
  else if(activeView==='review')renderReview(root);
  else if(activeView==='sharing')renderSharing(root);
  else if(activeView==='appearance')renderAppearance(root);
  bindFormEvents();enforceAccess(root);
}
function renderReview(root){const r=reviewProject(active);root.innerHTML=`<section class="review-hero ${r.ready?'ready':''}"><div><span>${r.ready?'READY FOR ISSUE REVIEW':'WORKING DRAFT'}</span><h2>${r.score}% ready</h2><p>${r.ready?'Critical requirements are complete. Review the content, then freeze the issue.':'Complete the critical items before freezing a formal issue.'}</p></div><button class="button primary" id="create-release" ${r.ready?'':'disabled'}>Freeze issue ${esc(active.fields.revision||'')}</button></section><section class="form-card"><div class="card-heading"><h2>Review results</h2><span>${r.critical} critical · ${r.warnings} warning${r.warnings===1?'':'s'}</span></div><div class="issue-list">${r.issues.length?r.issues.map(i=>`<button type="button" class="issue ${i.severity}" data-issue-code="${esc(i.code)}"><b>${i.severity==='critical'?'Resolve':'Warning'}</b><span>${esc(i.message)}</span><em>Go to issue →</em></button>`).join(''):'<div class="success-state">No recorded gaps.</div>'}</div></section><section class="form-card"><div class="card-heading"><h2>Frozen issues</h2><span>Unaffected by changes to the current draft</span></div><div class="release-list">${active.releases.length?active.releases.slice().reverse().map(r=>`<article><div><strong>${esc(r.revision)}</strong><span>Issue ${r.number} · ${esc(r.issueDate)} · ${r.readiness}% ready</span></div><button class="button ghost" data-restore-release="${r.id}">Restore as draft</button></article>`).join(''):'<p class="empty-cell">No frozen issues yet.</p>'}</div></section>`;}
async function goToIssue(code){const target=issueTarget(code,active);await showView(target.view);requestAnimationFrame(()=>{const element=$(target.selector),focus=target.focus?$(target.focus):element;if(!element){notify('The related section could not be located.');return;}element.scrollIntoView({behavior:'smooth',block:'center'});element.classList.add('issue-target');setTimeout(()=>element.classList.remove('issue-target'),2200);focus?.focus?.({preventScroll:true});});}
const safeFileName=name=>name.normalize('NFKD').replace(/[^a-zA-Z0-9._-]+/g,'-').replace(/-+/g,'-').slice(-120)||'file';
async function addAttachments(files){
  if(!session){notify('Sign in before uploading private files.');openAuth();return;}
  const allowed=new Set(['application/pdf','image/png','image/jpeg','text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.wordprocessingml.document']);
  for(const file of files){
    if(file.size>26214400){notify(`${file.name} is larger than 25 MB.`);continue;}
    if(!allowed.has(file.type)){notify(`${file.name} has an unsupported file type.`);continue;}
    const id=crypto.randomUUID(),path=`${session.user.id}/${active.id}/attachments/${id}-${safeFileName(file.name)}`;
    setCloudStatus('syncing',`Uploading ${file.name}…`);
    try{await uploadAttachment(file,path);active.attachments.push({id,path,name:file.name,size:file.size,type:file.type,uploadedAt:new Date().toISOString()});active.lists.appendices.push({title:file.name,reference:'',status:'Attached',location:file.name,attachmentId:id});}
    catch(error){notify(`Upload failed: ${error.message}`);}
  }
  persist();renderFormView();setCloudStatus('connected',session.user.email);
}
async function downloadStoredFile(id){const file=active.attachments.find(item=>item.id===id);if(!file)return;try{const blob=await downloadAttachment(file.path),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){notify(error.message);}}
async function removeStoredFile(id){const file=active.attachments.find(item=>item.id===id);if(!file||!await confirmAction('Delete attachment',`${file.name} will be permanently removed from secure storage.`))return;try{await deleteAttachment(file.path);active.attachments=active.attachments.filter(item=>item.id!==id);const appendix=active.lists.appendices.find(row=>row.attachmentId===id);if(appendix){appendix.status='Removed';appendix.location='—';}persist();renderFormView();notify('Attachment deleted.');}catch(error){notify(error.message);}}
function ensureLogoSlots(){active.style.logos=active.style.logos||[];while(active.style.logos.length<Number(active.style.logoCount||0))active.style.logos.push({id:`logo-slot-${active.style.logos.length+1}`,path:'',name:'',placement:'both'});}
async function setLogo(file,index){if(!session){notify('Sign in before uploading a private logo.');openAuth();return;}if(!['image/png','image/jpeg'].includes(file.type)||file.size>5242880){notify('Use a PNG or JPEG logo no larger than 5 MB.');return;}ensureLogoSlots();const slot=active.style.logos[index],old=slot?.path,path=`${session.user.id}/${active.id}/branding/${crypto.randomUUID()}-${safeFileName(file.name)}`;try{setCloudStatus('syncing','Uploading logo…');await uploadAttachment(file,path);active.style.logos[index]={id:slot?.id||crypto.randomUUID(),path,name:file.name,placement:slot?.placement||'both'};active.style.logoPath='';if(old)await deleteAttachment(old).catch(()=>{});persist();renderFormView();setCloudStatus('connected',session.user.email);notify(`Logo ${index+1} updated.`);}catch(error){setCloudStatus('error','Upload failed');notify(error.message);}}
async function removeLogo(index){ensureLogoSlots();const logo=active.style.logos[index];if(!logo?.path||!await confirmAction('Remove logo',`${logo.name||`Logo ${index+1}`} will be permanently removed from secure storage.`))return;try{await deleteAttachment(logo.path);active.style.logos[index]={...logo,path:'',name:''};persist();renderFormView();notify('Project logo removed.');}catch(error){notify(error.message);}}
async function deleteProjectStorage(project){const paths=[...(project.attachments||[]).map(file=>file.path),...(project.style.logos||[]).map(logo=>logo.path),project.style.logoPath].filter(Boolean);await Promise.all([...new Set(paths)].map(path=>deleteAttachment(path).catch(()=>null)));}
function bindFormEvents(){
  $$('[data-field]').forEach(el=>el.addEventListener('input',()=>{active.fields[el.dataset.field]=el.value;changed();}));
  $$('[data-list]').forEach(el=>el.addEventListener('input',()=>{active.lists[el.dataset.list][+el.dataset.row][el.dataset.col]=el.value;changed();}));
  $$('[data-add-row]').forEach(btn=>btn.addEventListener('click',()=>{const key=btn.dataset.addRow;active.lists[key].push(Object.fromEntries(listSchemas[key].columns.map(([column,,type,options])=>[column,type==='select'?options[0]:'' ])));changed();renderFormView();}));
  $$('[data-delete-row]').forEach(btn=>btn.addEventListener('click',()=>{active.lists[btn.dataset.deleteRow].splice(+btn.dataset.row,1);changed();renderFormView();}));
  $$('[data-export-csv]').forEach(btn=>btn.addEventListener('click',()=>{const key=btn.dataset.exportCsv;downloadBlob(new Blob([toCsv(active.lists[key],listSchemas[key])],{type:'text/csv;charset=utf-8'}),`${active.fields.projectCode||'BEP'}-${key}.csv`);}));
  $$('[data-import-csv]').forEach(btn=>btn.addEventListener('click',()=>{csvTarget=btn.dataset.importCsv;$('#csv-import').click();}));
  $$('[data-module]').forEach(el=>el.addEventListener('change',()=>{active.moduleStates[el.dataset.module]=el.value;const mod=modules.find(m=>m.id===el.dataset.module);if(el.value!=='not_applicable'&&mod?.depends)for(const dep of mod.depends)if(active.moduleStates[dep]==='not_applicable')active.moduleStates[dep]='required';changed();renderFormView();notify('The module and its dependencies were updated.');}));
  $$('[data-note]').forEach(el=>el.addEventListener('input',()=>{active.notes[el.dataset.note]=el.value;changed();}));
  $$('[data-style]').forEach(el=>el.addEventListener('input',()=>{active.style[el.dataset.style]=el.type==='checkbox'?el.checked:el.value;changed();}));
  $$('[data-open-preview]').forEach(el=>el.addEventListener('click',()=>showView('preview')));
  $('#attachment-upload')?.addEventListener('change',event=>addAttachments([...event.target.files]));
  $$('[data-download-file]').forEach(button=>button.addEventListener('click',()=>downloadStoredFile(button.dataset.downloadFile)));
  $$('[data-delete-file]').forEach(button=>button.addEventListener('click',()=>removeStoredFile(button.dataset.deleteFile)));
  $('#logo-count')?.addEventListener('change',event=>{active.style.logoCount=Number(event.target.value);ensureLogoSlots();changed();renderFormView();});
  $$('[data-logo-upload]').forEach(input=>input.addEventListener('change',event=>{const file=event.target.files[0];if(file)setLogo(file,Number(input.dataset.logoUpload));}));
  $$('[data-remove-logo]').forEach(button=>button.addEventListener('click',()=>removeLogo(Number(button.dataset.removeLogo))));
  $$('[data-logo-placement]').forEach(select=>select.addEventListener('change',()=>{ensureLogoSlots();active.style.logos[Number(select.dataset.logoPlacement)].placement=select.value;changed();}));
  $$('[data-issue-code]').forEach(button=>button.addEventListener('click',()=>goToIssue(button.dataset.issueCode)));
  $$('[data-copy-link]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copyLink);notify('Link copied.');}catch{notify('Copy failed. Select and copy the link manually.');}}));
  $('#public-share-form')?.addEventListener('submit',createSharePreview);
  $('#project-invite-form')?.addEventListener('submit',createCollaborationInvite);
  $$('[data-revoke-share]').forEach(button=>button.addEventListener('click',()=>revokeSharePreview(button.dataset.revokeShare)));
  $$('[data-revoke-invite]').forEach(button=>button.addEventListener('click',()=>revokeInvite(button.dataset.revokeInvite)));
  $$('[data-remove-collaborator]').forEach(button=>button.addEventListener('click',()=>removeCollaborator(button.dataset.removeCollaborator)));
  $('#leave-project')?.addEventListener('click',leaveProject);
  $('#export-workbook')?.addEventListener('click',()=>{downloadBlob(createWorkbook(active.lists),`${active.fields.projectCode||'BEP'}-schedules.xlsx`);notify('Excel workbook created.');});
  $('#import-workbook')?.addEventListener('click',()=>$('#workbook-import').click());
  $('#new-template')?.addEventListener('click',()=>{$('#template-form').reset();$('#template-form [name="version"]').value='1.0';$('#template-dialog').showModal();});
  $$('[data-apply-template]').forEach(btn=>btn.addEventListener('click',()=>applySelectedTemplate(btn.dataset.applyTemplate)));
  $$('[data-delete-template]').forEach(btn=>btn.addEventListener('click',async()=>{const template=templates.find(t=>t.id===btn.dataset.deleteTemplate);if(template&&await confirmAction('Delete template',`${template.name} will be permanently deleted from your private template library.`)){try{await deleteCloudTemplate(template.id);templates=templates.filter(t=>t.id!==template.id);renderFormView();notify('Template deleted.');}catch(error){notify(error.message);}}}));
  $('#clear-conflicts')?.addEventListener('click',()=>{active.templateConflicts=[];persist();renderFormView();renderReadiness();notify('Template conflicts marked as reviewed.');});
  $('#create-release')?.addEventListener('click',()=>{const n=createRelease(active);persist();renderFormView();notify(`Issue ${n} was frozen.`);});
  $$('[data-restore-release]').forEach(btn=>btn.addEventListener('click',async()=>{if(await confirmAction('Restore issue','The current draft will be replaced with this issue snapshot.')){restoreRelease(active,btn.dataset.restoreRelease);persist();renderFormView();renderReadiness();notify('The issue was restored as an editable draft.');}}));
}
function releaseLogoUrls(){for(const item of logoObjectUrls)if(item?.url)URL.revokeObjectURL(item.url);logoObjectUrls=[];}
async function loadLogoUrls(){releaseLogoUrls();ensureLogoSlots();if(!session)return [];const configured=active.style.logos.slice(0,Number(active.style.logoCount||0));logoObjectUrls=await Promise.all(configured.map(async logo=>{if(!logo.path)return {...logo,url:''};try{return {...logo,url:URL.createObjectURL(await downloadAttachment(logo.path))};}catch(error){notify(`Logo preview unavailable: ${error.message}`);return {...logo,url:''};}}));return logoObjectUrls;}
async function refreshSharingData(){
  if(!accessOwner()){publicShares=[];projectInvites=[];collaborators=[];return;}
  [publicShares,projectInvites,collaborators]=await Promise.all([fetchPublicShares(active.id),fetchProjectInvites(active.id),fetchProjectCollaborators(active.id)]);
}
async function createSharePreview(event){
  event.preventDefault();const form=event.currentTarget,data=new FormData(form),button=form.querySelector('button[type="submit"]'),days=Number(data.get('days'));button.disabled=true;button.textContent='Publishing…';
  try{
    const configured=(active.style.logos||[]).slice(0,Number(active.style.logoCount||0)),publicLogos=[];
    for(const logo of configured)if(logo.path){const url=await createSignedAttachmentUrl(logo.path,days*86400);publicLogos.push({name:logo.name,placement:logo.placement,url});}
    const result=await createPublicShare(active,String(data.get('title')).trim(),days,publicLogos);lastShareLink=result.url;await refreshSharingData();renderFormView();notify('Public preview published.');
  }catch(error){notify(error.message);}finally{button.disabled=false;button.textContent='Create public preview';}
}
async function revokeSharePreview(id){const item=publicShares.find(row=>row.id===id);if(!item||!await confirmAction('Revoke public preview','The BEP preview link will stop working immediately.'))return;try{await revokePublicShare(id);lastShareLink='';await refreshSharingData();renderFormView();notify('Public preview revoked.');}catch(error){notify(error.message);}}
async function createCollaborationInvite(event){event.preventDefault();const form=event.currentTarget,data=new FormData(form),button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Creating…';try{const result=await createProjectInvite(active.id,String(data.get('role')),Number(data.get('days')));lastInviteLink=result.url;await refreshSharingData();renderFormView();notify('Invitation link created.');}catch(error){notify(error.message);}finally{button.disabled=false;button.textContent='Create invitation link';}}
async function revokeInvite(id){if(!await confirmAction('Revoke invitation','This invitation link will no longer be accepted.'))return;try{await revokeProjectInvite(id);lastInviteLink='';await refreshSharingData();renderFormView();notify('Invitation revoked.');}catch(error){notify(error.message);}}
async function removeCollaborator(userId){const member=collaborators.find(row=>row.user_id===userId);if(!member||!await confirmAction('Remove collaborator',`${member.collaborator_email||'This user'} will lose access to the BEP.`))return;try{await removeProjectCollaborator(active.id,userId);await refreshSharingData();renderFormView();notify('Collaborator removed.');}catch(error){notify(error.message);}}
