$('#signin-form').addEventListener('submit',async event=>{
  event.preventDefault();const form=event.currentTarget,data=new FormData(form),email=String(data.get('email')).trim(),password=String(data.get('password')),remember=data.get('remember')==='on';
  const token=captchaToken('signin');if(!token){showAuthMessage('Complete the security verification before signing in.');return;}
  clearAuthMessage();setAuthBusy(form,true,'Signing in…');
  try{session=await signIn(email,password,remember,token);await finishSignedIn();}
  catch(error){showAuthMessage(error.message);}
  finally{resetTurnstile('signin');setAuthBusy(form,false);}
});
$('#signup-form').addEventListener('submit',async event=>{
  event.preventDefault();const form=event.currentTarget,data=new FormData(form),email=String(data.get('email')).trim(),password=String(data.get('password')),confirmPassword=String(data.get('confirmPassword')),remember=data.get('remember')==='on';
  if(password!==confirmPassword){showAuthMessage('The password confirmation does not match.');return;}
  const token=captchaToken('signup');if(!token){showAuthMessage('Complete the security verification before creating your account.');return;}
  clearAuthMessage();setAuthBusy(form,true,'Creating account…');
  try{
    const result=await signUp(email,password,remember,inviteTokenFromUrl()?location.href:location.origin,token);
    if(result?.access_token){session=result;await finishSignedIn();}
    else showAuthView('signin',{message:'Account created. Check your email to confirm it, then sign in.',success:true});
  }catch(error){showAuthMessage(error.message);}
  finally{resetTurnstile('signup');setAuthBusy(form,false);}
});
$('#forgot-form').addEventListener('submit',async event=>{
  event.preventDefault();const form=event.currentTarget,email=String(new FormData(form).get('email')).trim();clearAuthMessage();setAuthBusy(form,true,'Sending…');
  const token=captchaToken('forgot');if(!token){setAuthBusy(form,false);showAuthMessage('Complete the security verification before requesting a reset link.');return;}
  try{await requestPasswordReset(email,location.origin,token);showAuthMessage('If an account exists for this email, a reset link has been sent. Check your inbox and spam folder.',true);}
  catch(error){showAuthMessage(error.message);}
  finally{resetTurnstile('forgot');setAuthBusy(form,false);}
});
$('#reset-form').addEventListener('submit',async event=>{
  event.preventDefault();const form=event.currentTarget,data=new FormData(form),password=String(data.get('password')),confirmPassword=String(data.get('confirmPassword'));
  if(password!==confirmPassword){showAuthMessage('The password confirmation does not match.');return;}
  clearAuthMessage();setAuthBusy(form,true,'Updating…');
  try{await updatePassword(password);await signOut();session=null;showAuthView('signin',{message:'Password updated successfully. Sign in with your new password.',success:true});}
  catch(error){showAuthMessage(error.message);}
  finally{setAuthBusy(form,false);}
});
window.addEventListener('online',()=>{if(session)syncWorkspace();});

async function showPublicPreview(token){
  document.body.classList.remove('auth-locked');document.body.classList.add('public-preview');$('#auth-screen').hidden=true;$('.topbar').hidden=true;$('#dashboard').hidden=true;$('#editor').hidden=false;$('.sidebar').hidden=true;$('.workarea').hidden=true;$('#document-pane').classList.add('show');
  const toolbar=$('.document-toolbar');toolbar.innerHTML='<span>PUBLIC BEP PREVIEW · READ ONLY</span><button class="button primary" id="public-print">Print / PDF</button>';
  try{
    const data=await fetchPublicShare(token);if(!data?.project)throw new Error('This preview link is invalid, expired or has been revoked.');active=data.project;document.title=`${data.title||active.fields.projectName} · BEP Preview`;document.documentElement.style.setProperty('--accent',active.style?.accent||'#15557a');document.documentElement.style.setProperty('--doc-font',active.style?.font==='serif'?'Georgia,serif':'Arial,sans-serif');await renderPaginatedDocument($('#document'),buildDocument(active,reviewProject(active),data.logos||[]),active,data.logos||[]);$('#public-print').addEventListener('click',()=>window.print());
  }catch(error){$('#document').innerHTML=`<section class="public-error"><span class="eyebrow">PUBLIC PREVIEW</span><h1>Preview unavailable</h1><p>${esc(error.message)}</p></section>`;$('#public-print').hidden=true;}
}

async function initialize(){
  const publicToken=new URLSearchParams(location.search).get('share');if(publicToken){await showPublicPreview(publicToken);return;}
  renderDashboard();setCloudStatus('syncing','Connecting…');
  try{
    const redirect=await consumeAuthRedirect();
    if(redirect){session=redirect.session;if(redirect.type==='recovery'){setCloudStatus('','Password recovery');showAuthView('reset');return;}}
    if(!session)session=await restoreSession();
    if(session){await finishSignedIn();}
    else{setCloudStatus('','Sign in');showAuthView('signin',{message:inviteTokenFromUrl()?'Sign in or create an account to accept this BEP invitation.':''});}
  }catch(error){setCloudStatus('error','Authentication error');showAuthView('signin',{message:error.message});}
}
initialize();
